//! What loading checks beyond the JSON Schemas: each target kind's `validate`
//! (`src/targets/*.ts`) and the rule's file roles.

use std::sync::LazyLock;

use regex::Regex;

use crate::model::{
    CheckTarget, Decision, Language, Level, Mode, OneOrMany, Pack, Rule, Stage, Target,
    WhereCondition,
};
use crate::roles;

// `ADAPTERS`: the tool adapters (§16) a check command must ask through `forge_do <tool>
// <operation>`, with the pattern that recognises a direct run when the adapter sets one
// (`direct`). Generated by `build.rs` from the checker's adapter files, the one list of them.
include!(concat!(env!("OUT_DIR"), "/adapters.rs"));

/// Project tools whose name has a "-" (`PROJECT_TOOLS` in `src/core/tools.ts`).
const DASHED_PROJECT_TOOLS: &[&str] = &["vue-tsc", "mikro-orm", "graphql-codegen", "better-auth"];

fn escape_tool(tool: &str) -> String {
    tool.replace('.', r"\.").replace('-', r"\-")
}

/// `directPattern`: a check command that runs the adapted tool directly.
/// A JavaScript pattern of the adapters' as the `regex` crate reads it: `\b` is ASCII, as in
/// JavaScript, and the trailing lookahead `(?=…)` (which `regex` lacks) becomes a group,
/// which changes what is matched but not whether something is.
fn js_pattern(src: &str) -> String {
    let src = src.replace(r"\b", r"(?-u:\b)");
    match src.rfind("(?=") {
        Some(i) if src.ends_with(')') => format!("{}(?:{}", &src[..i], &src[i + 3..]),
        _ => src,
    }
}

static DIRECT: LazyLock<Vec<(&'static str, Regex)>> = LazyLock::new(|| {
    ADAPTERS
        .iter()
        .map(|(tool, direct)| {
            let src = direct.map_or_else(
                || format!(r"(^|[\s;&|(`!]|\$\(){}(?=$|[\s;&|)`])", escape_tool(tool)),
                str::to_string,
            );
            (
                *tool,
                Regex::new(&format!("(?m){}", js_pattern(&src))).expect("adapter regex"),
            )
        })
        .collect()
});

static DASHED: LazyLock<Vec<(&'static str, Regex)>> = LazyLock::new(|| {
    DASHED_PROJECT_TOOLS
        .iter()
        .map(|tool| {
            (
                *tool,
                Regex::new(&js_pattern(&format!(
                    r"(^|[\s;&|(`]|\$\()({})(?=$|[\s;&|)`])",
                    escape_tool(tool)
                )))
                .expect("tool regex"),
            )
        })
        .collect()
});
static SINGLE_QUOTED: LazyLock<Regex> = LazyLock::new(|| Regex::new("'[^']*'").expect("regex"));
static FORGE_DO: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?-u:\b)forge_do\s+[a-z][a-z0-9-]*").expect("regex"));
static WRAPPED: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?-u:\b)forge_(exec_tool|do)\s+$").expect("regex"));

/// `directDashedTools`: dashed project tools a command runs directly, not through `forge_exec_tool`.
fn direct_dashed_tools(cmd: &str) -> Vec<&'static str> {
    let mut out = Vec::new();
    for (tool, re) in DASHED.iter() {
        let mut at = 0;
        // every occurrence (the lookahead's stand-in consumes a character the next may start with)
        while let Some(c) = re.captures_at(cmd, at) {
            let (lead, name) = (
                c.get(1).map_or(0, |g| g.end()),
                c.get(2).expect("tool group"),
            );
            if !WRAPPED.is_match(&cmd[..lead]) && !out.contains(tool) {
                out.push(*tool);
            }
            at = name.end();
        }
    }
    out
}

/// The named facts `when.facts` and `detect.facts_any` may use, with their values (forge-detect
/// computes them: `python.pm` from the packaging files, `js.pm` from the pinned manager or lock).
pub const FACTS: &[(&str, &[&str])] = &[
    (
        "python.pm",
        &["uv", "poetry", "pdm", "pipenv", "pip", "none"],
    ),
    ("js.pm", &["npm", "pnpm", "yarn", "bun", "none"]),
];

fn check_facts<'a>(
    facts: impl IntoIterator<Item = (&'a String, &'a OneOrMany<String>)>,
) -> Result<(), String> {
    for (name, want) in facts {
        let Some((_, values)) = FACTS.iter().find(|(n, _)| n == name) else {
            let known: Vec<&str> = FACTS.iter().map(|(n, _)| *n).collect();
            return Err(format!(
                "unknown fact {name:?} (known: {})",
                known.join(", ")
            ));
        };
        if let Some(v) = want
            .as_slice()
            .iter()
            .find(|v| !values.contains(&v.as_str()))
        {
            return Err(format!(
                "fact {name} has no value {v:?} (its values: {})",
                values.join(", ")
            ));
        }
    }
    Ok(())
}

/// Checks a pack.yaml beyond its schema.
pub fn validate_pack(pack: &Pack) -> Result<(), String> {
    if pack.level == Level::User && pack.detect.is_some() {
        return Err("invalid pack: a user-level pack has no detect".into());
    }
    if let Some(f) = pack.detect.as_ref().and_then(|d| d.facts_any.as_ref()) {
        check_facts(f).map_err(|e| format!("invalid pack: detect.facts_any: {e}"))?;
    }
    // items may share an id (one text under alternative conditions: the first that holds is
    // rendered), but then they share the text too
    for (i, item) in pack.context.iter().enumerate() {
        if let Some(w) = &item.when {
            check_facts(&w.facts).map_err(|e| format!("invalid pack: /context/{i}/when: {e}"))?;
        }
        if let Some(id) = &item.id
            && pack.context[..i]
                .iter()
                .any(|o| o.id.as_ref() == Some(id) && o.text != item.text)
        {
            return Err(format!(
                "invalid pack: /context/{i}: id {id:?} names another text already"
            ));
        }
    }
    Ok(())
}

/// A check target's fields that depend on each other.
fn check_target_fields(c: &CheckTarget) -> Result<(), String> {
    if c.rerun.is_some() && c.stage != Stage::Test {
        return Err("invalid rule: rerun is for stage test".into());
    }
    if c.format_stdin.is_some() && !matches!(c.stage, Stage::Format | Stage::Lint) {
        return Err("invalid rule: format_stdin is for stages format and lint".into());
    }
    if c.fix_lints.is_some() && (c.fix_run.is_none() || c.changed_run.is_none()) {
        return Err("invalid rule: fix_lints needs fix_run and changed_run".into());
    }
    if c.config_files.is_some() && c.stage != Stage::Lint {
        return Err("invalid rule: config_files is for stage lint".into());
    }
    Ok(())
}

fn where_ok(w: &WhereCondition) -> bool {
    match w {
        WhereCondition::Deprecated(b) => *b,
        WhereCondition::Not(inner) => where_ok(inner),
        _ => true,
    }
}

/// The checks of a rule's fields that depend on each other.
fn check_fields(rule: &Rule) -> Result<(), String> {
    if rule.review.is_some()
        && !rule.enforce.iter().any(|t| match t {
            Target::Guard(g) => g.decision == Decision::Ask,
            Target::Check(c) => c.run.trim() == "forge_test_edits",
            _ => false,
        })
    {
        return Err("invalid rule: review is the question for an ask: it needs a guard ask target or the test-edit check".into());
    }
    for deps in [
        rule.when.as_ref().map(|w| &w.deps),
        rule.examples.as_ref().and_then(|e| e.deps.as_ref()),
    ]
    .into_iter()
    .flatten()
    {
        if let Some(d) = deps.iter().find(|d| d.version.is_none()) {
            return Err(format!(
                "invalid rule: dependency {} needs a version",
                d.name
            ));
        }
    }
    for t in &rule.enforce {
        match t {
            Target::Guard(g) if g.command.is_none() && g.check.is_none() => {
                return Err("invalid rule: a guard target needs command or check".into());
            }
            Target::AstGrep(a) if a.where_.is_some() || a.needs.is_some() => {
                if a.where_.is_none() {
                    return Err("invalid rule: needs requires where".into());
                }
                if !matches!(a.mode, Mode::Forbid | Mode::Advise) {
                    return Err("invalid rule: a where target's mode is forbid or advise".into());
                }
                if !a.where_.iter().flatten().all(|(_, w)| where_ok(w)) {
                    return Err(
                        "invalid rule: where deprecated is written `deprecated: true`".into(),
                    );
                }
            }
            Target::Check(c) => check_target_fields(c)?,
            _ => {}
        }
    }
    Ok(())
}

/// Checks a rule's targets and roles (beyond the schema).
pub fn validate_rule(rule: &Rule) -> Result<(), String> {
    check_fields(rule)?;
    for t in &rule.enforce {
        match t {
            Target::Check(c) => {
                for command in c.commands() {
                    // single-quoted text is data, not a command of this shell
                    let code = SINGLE_QUOTED.replace_all(command, "''");
                    let code = FORGE_DO.replace_all(&code, "forge_do _");
                    for (tool, re) in DIRECT.iter() {
                        if re.is_match(&code) {
                            return Err(format!(
                                "invalid rule: run {tool} as \"forge_do {tool} <operation>\" (§16: its adapter knows how each release does it)"
                            ));
                        }
                    }
                    if let Some(tool) = direct_dashed_tools(command).first() {
                        return Err(format!(
                            "invalid rule: run {tool} as \"forge_exec_tool {tool}\" (a name with \"-\" has no wrapper function, so it would not be the project's own)"
                        ));
                    }
                }
            }
            Target::AstGrep(a) => {
                // deprecated uses are answered by the TypeScript engine (§15.7)
                let where_json = serde_json::to_string(&a.where_.clone().unwrap_or_default())
                    .unwrap_or_default();
                if rule.scope.language == Language::Python && where_json.contains("\"deprecated\"")
                {
                    return Err(
                        "invalid rule: where deprecated is answered for TypeScript only (§15.7); Python's deprecations are ty's deprecated rule".into()
                    );
                }
            }
            _ => {}
        }
    }
    let unknown = roles::unknown_roles(rule);
    if !unknown.is_empty() {
        let names: Vec<String> = unknown.iter().map(|r| format!("@{r}")).collect();
        return Err(format!(
            "invalid rule: unknown file role {} (§15.4)",
            names.join(", ")
        ));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::direct_dashed_tools;

    #[test]
    fn dashed_tools() {
        assert_eq!(direct_dashed_tools("vue-tsc --noEmit"), ["vue-tsc"]);
        assert!(direct_dashed_tools("forge_exec_tool vue-tsc --noEmit").is_empty());
        assert!(direct_dashed_tools("echo x-vue-tsc").is_empty());
    }
}
